 const lang=()=>root.CM_I18N?.getLanguage?.()||'zh',w=(zh,en)=>lang()==='en'?en:zh,tr=s=>root.CM_I18N?.t(s)||String(s||'');
 const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
