 const groupName=id=>tr(D.groups[id]),goalName=id=>({stay:w('住得下','Room to stay'),social:w('处得来','Community ties'),comfort:w('住得舒服','Liveability')})[id]||id;
 const status=value=>value>=68?{word:w('状态稳定','Stable'),cls:''}:value>=40?{word:w('仍需支持','Needs support'),cls:'amber'}:{word:w('居住受到影响','Home life affected'),cls:'red'};
